"""Dependency-free, deterministic static site generator for GitHub Pages."""
import json
from pathlib import Path
from html import escape as esc
from datetime import date, timedelta

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'considered'
SITE.mkdir(exist_ok=True)
D = json.loads((ROOT / 'research/data.json').read_text())
S = D['sources']
NAV = [('index','Overview','01'),('hotels','Hotels','02'),('restaurants','Michelin dining','03'),('activities','Things to do','04'),('itinerary','Trip outline','05'),('dates','Dates & costs','06'),('review','Flagged for review','07'),('suggestions','Suggestions & questions','08'),('sources','Sources & method','09')]

def link(url, label):
    return f'<a href="{esc(url, quote=True)}" target="_blank" rel="noopener noreferrer">{esc(label)} <span aria-hidden="true">↗</span></a>'

def refs(ids):
    return '<div class="refs">' + ''.join(link(S[i]['url'], S[i]['title']) for i in ids) + '</div>'

def val(x):
    return esc(x) if x is not None else '<span class="missing"><span class="empty-value" aria-label="No confirmed value"></span><span class="badge amber">Unverified</span></span>'

def note(text):
    return f'<div class="notice"><span aria-hidden="true">i</span><div>{text}</div></div>'

def table(headers, rows, caption, filterable=False):
    controls = ''
    if filterable:
        controls = '<div class="table-tools"><label>Search this table <input type="search" class="table-search" placeholder="Name, area, cuisine…"></label><span class="result-count" aria-live="polite"></span></div>'
    out = controls + '<div class="table-wrap"><table><caption>'+esc(caption)+'</caption><thead><tr>' + ''.join('<th scope="col">'+esc(h)+'</th>' for h in headers) + '</tr></thead><tbody>'
    for row in rows:
        out += '<tr>' + ''.join(f'<td data-label="{esc(h)}">{c}</td>' for h,c in zip(headers,row)) + '</tr>'
    return out + '</tbody></table><p class="no-results" hidden>No matching entries. Try another search.</p></div>'

def card(eyebrow,title,body,href=None):
    return f'<article class="card"><span class="eyebrow">{eyebrow}</span><h3>{title}</h3><p>{body}</p>'+ (f'<a class="text-link" href="{href}">Explore details <span aria-hidden="true">→</span></a>' if href else '') + '</article>'

def social(items):
    return '<div class="refs">'+''.join(link(u,l) for l,u in items)+'</div>' if items else val(None)

def page(key,title,subtitle,body):
    nav = ''.join(f'<a href="{k}.html" '+('aria-current="page"' if k==key else '')+f'><span class="nav-num">{n}</span>{label}</a>' for k,label,n in NAV)
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Source-linked China trip planning for two adults, February–March 2027. Confirmed facts, transparent gaps, and a Shanghai research shortlist."><meta name="theme-color" content="#722e39"><title>{esc(title)} · China, considered</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a href="index.html" class="brand"><span class="seal" aria-hidden="true">C</span><span>China, considered<small>A JOURNEY FOR TWO</small></span></a><div class="sidebar-label">YOUR TRAVEL NOTEBOOK</div><nav aria-label="Main navigation">{nav}</nav><div class="sidebar-bottom"><span class="dot"></span> Research snapshot<small>25 November 2026 · UTC<br>No reservations made</small></div></aside>
<div class="workspace"><header class="topbar"><span>TRIP PLANNING <span class="slash">/</span> CHINA 2027</span><div><span class="chip">2 adults</span><button class="print" type="button">Print / Save PDF</button></div></header><main id="main"><div class="page-heading"><div><div class="eyebrow">THE FEBRUARY–MARCH EDITION</div><h1>{title}</h1><p class="lead">{subtitle}</p></div><span class="status"><span class="dot"></span> Planning baseline</span></div>{body}</main><footer><span>Thoughtfully planned. Transparently sourced.</span><span>Checked 25 Nov 2026 · All venue hours are Shanghai local time (UTC+8).</span><a href="sources.html">Evidence & limitations →</a></footer></div></body></html>'''
    (SITE/f'{key}.html').write_text(html)

