body+='''<section class="section"><div class="section-title"><h2>How the shortlist fits together</h2><a href="restaurants.html#clusters">View dining clusters →</a></div><div class="grid two">'''+card('WORKING RECOMMENDATION','One base, less packing','Use Shanghai as a research starting point, with a seven-night baseline and optional longer stay. This is an editorial plan, not evidence that Shanghai is cheaper or denser than other Chinese cities.')+card('BEFORE SPENDING','Keep the decision reversible','Do not make a non-refundable booking from this snapshot. A dated total, an eligible king room, refund conditions, and complete door-to-door routes are needed to support a hotel decision.')+'</div></section>'
body+= '<section class="panel"><div><span class="eyebrow">AUDIT TRAIL</span><h2>Every fact has a place to check.</h2><p>Official sources establish operational facts. Social links are previews only. Recommendations are labeled as proposals.</p></div><a class="button" href="sources.html">Open source register →</a></section>'
page('index','Your China escape','A food-led trip for two. Clear choices, honest gaps, and room to explore.',body)

