for q,known,nextstep in questions:
    body+=f'<details class="question"><summary>{q}</summary><p>{known}</p><p><strong>How to close the gap:</strong> {nextstep}</p><p class="muted">Answer status: unresolved. No automatic assumption.</p></details>'
body+='</section><section class="panel"><div><h2>Other site enhancements to review</h2><p>Consider dated evidence snapshots, quote expiry labels, a full restaurant inventory, branch-specific videos, an accessible evidence-backed map and a configurable budget comparison. These are not silently implemented because they require new evidence, maintenance or personal parameters. Current search, print, category navigation and blank-value safeguards are already implemented.</p></div></section>'
page('suggestions','Better decisions, before more features','A dedicated review space for missing information and the next most useful work.',body)

rows=[]
for id,s in S.items():
    identity = {'ig-taian': 'm-taian', 'ig-fu': 'm-fu', 'ig-da': 'da'}.get(id)
    source_links = link(s['url'],'Open primary source') + (refs([identity]) if identity else '')
    rows.append([f'<strong>{esc(s["title"])}</strong><small>{esc(s["kind"])}</small>',esc(s['checked']),esc(s['observed']),source_links])
body=note('<strong>Verification is field-level, not a blanket label.</strong> “Official” identifies the publisher, not a guarantee of accuracy or future availability. All published operational facts below were read from primary sources. Missing fields are left blank and flagged. Social profiles are previews only; no blog-derived prices or transit estimates are promoted to verified facts.')
body+='<section class="section"><div class="grid two">'+card('METHOD','Bounded, source-first research','Repository audit: only an 11-byte README existed at the start, with no app or data. This site is a new static dashboard. Shanghai is a limited shortlist, not all China or a complete Michelin database.')+card('FRESHNESS','A snapshot, not a live feed','Observed 25 November 2026 UTC. Ratings, schedules, prices, links and availability can change. No future monitoring is running. All 2027 reservation availability must be reconfirmed.')+'</div></section>'
body+=table(['Source / authority','Checked UTC','Fields observed / limitation','Manual review'],rows,'Primary-source register and exact scope of the observations.',True)
body+='<section class="section"><h2>Downloads & audit trail</h2><div class="refs"><a href="../research/data.json" download>Structured findings · JSON ↓</a><a href="../research/README.md">Research notes & irregularities</a><a href="../COORDINATION.md">Shared task board</a><a href="https://github.com/kanlerxz87-cyber/ChinaFun3">Repository ↗</a></div><p>Blank factual values are stored as null, not zero. On-screen Unverified labels are status markers, not substituted values. No star/price-band conversion, currency-rate assumption or nightly-rate multiplication is used. Internal proposals and calendar calculations are labeled as such; their venue links establish only the underlying venue facts.</p><p>Internal-link and schema tests run offline. External sources were checked through research fetches, not an exhaustive automated live-link crawl. A working source link today is not a guarantee for the trip dates.</p></section>'
page('sources','Follow the evidence','Official links, observed fields, source dates, and the limits of what was checked.',body)
print('Built',len(NAV),'static pages.')
